+function OperandAt(const Txt, Op: RawUtf8; Index, Item: integer): double;
+var
+  p, i: PtrInt;
+  line: RawUtf8;
+begin
+  p := PosEx(Op, Txt);
+  for i := 0 to Index do
+  begin
+    while (p > 1) and
+          (Txt[p - 1] <> #10) do
+      dec(p);
+    dec(p); // the #10 before the line
+  end;
+  line := copy(Txt, p + 1, PosEx(#10, Txt, p + 1) - p - 1);
+  result := GetExtended(pointer(GetCsvItem(pointer(line), Item, ' ')));
+end;
